document.querySelectorAll('.ilt').forEach(screen => {
  const scroller = screen.querySelector('.ilt__sc'), title = screen.querySelector('.ilt__lt');
  const sync = () => screen.classList.toggle('is-collapsed', scroller.scrollTop > title.offsetHeight - 8);
  scroller.addEventListener('scroll', sync, { passive: true }); sync();
});
